package com.example.lab21; import android.database.Cursor; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { EditText etId,etName,etCourse; TextView tvResult; DatabaseHelper db; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etId=findViewById(R.id.etId);etName=findViewById(R.id.etName);etCourse=findViewById(R.id.etCourse);tvResult=findViewById(R.id.tvResult);Button ins=findViewById(R.id.btnInsert),view=findViewById(R.id.btnView),upd=findViewById(R.id.btnUpdate),del=findViewById(R.id.btnDelete);db=new DatabaseHelper(this);
ins.setOnClickListener(v->{String n=etName.getText().toString().trim(),c=etCourse.getText().toString().trim();if(n.isEmpty()||c.isEmpty()){toast("Please enter Name and Course");return;}toast(db.insertStudent(n,c)?"Student Inserted Successfully":"Insertion Failed");});
view.setOnClickListener(v->{Cursor cur=db.getAllStudents();StringBuilder out=new StringBuilder();while(cur.moveToNext())out.append("ID: ").append(cur.getInt(0)).append("\nName: ").append(cur.getString(1)).append("\nCourse: ").append(cur.getString(2)).append("\n--------------------\n");if(out.length()==0)out.append("No Student Records Found");tvResult.setText(out.toString());cur.close();});
upd.setOnClickListener(v->{String id=etId.getText().toString().trim(),n=etName.getText().toString().trim(),c=etCourse.getText().toString().trim();if(id.isEmpty()||n.isEmpty()||c.isEmpty()){toast("Please enter all details");return;}toast(db.updateStudent(id,n,c)?"Student Updated Successfully":"Student ID not found");});
del.setOnClickListener(v->{String id=etId.getText().toString().trim();if(id.isEmpty()){toast("Enter Student ID");return;}toast(db.deleteStudent(id)?"Student Deleted Successfully":"Student ID not found");});}
void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();} }
